interface ProcessedFloor {
    floorNumber: number;
    width: number;
    height: number;
}
/**
 * Calculates layout metrics to determine if a set of floors can fit onto a given page size.
 * This function is used by both PDF generation and printing utilities to decide on page breaks.
 */
export const calculateLayoutMetrics = (
  floorsToLayout: { floorIndex: number; units: { unit: PlacedUnit; r: number; c: number; }[] }[],
  allUnitPositions: { unit: PlacedUnit; r: number; c: number; floor: number }[],
  pageWidth: number,
  pageHeight: number,
  BORDER_MARGIN: number
): { fits: boolean } => {
    if (floorsToLayout.length === 0) return { fits: true };

    const isLandscape = pageWidth > pageHeight;
    const availableWidth = pageWidth - BORDER_MARGIN * 2;
    const availableHeight = pageHeight - BORDER_MARGIN * 2;

    const uniqueRows = [...new Set(allUnitPositions.map(u => u.r))].sort((a, b) => a - b);
    const uniqueCols = [...new Set(allUnitPositions.map(u => u.c))].sort((a, b) => a - b);
    const rowHeights = Object.fromEntries(uniqueRows.map(r => [r, Math.max(0, ...allUnitPositions.filter(u => u.r === r).map(u => u.unit.dimensions.tsuma))]));
    const colWidths = Object.fromEntries(uniqueCols.map(c => [c, Math.max(0, ...allUnitPositions.filter(u => u.c === c).map(u => u.unit.dimensions.keta))]));

    const processedFloors: ProcessedFloor[] = floorsToLayout.map(({ floorIndex, units }) => {
      if (units.length === 0) return null;

      const minR = Math.min(...units.map(u => u.r));
      const maxR = Math.max(...units.map(u => u.r));
      const minC = Math.min(...units.map(u => u.c));
      const maxC = Math.max(...units.map(u => u.c));

      let totalWidth = 0;
      for (let c = minC; c <= maxC; c++) totalWidth += colWidths[c] || 0;
      totalWidth += (maxC - minC) * NOMINAL_DOT_SPACING;

      let totalHeight = 0;
      for (let r = minR; r <= maxR; r++) totalHeight += rowHeights[r] || 0;
      totalHeight += (maxR - minR) * NOMINAL_DOT_SPACING;

      return { floorNumber: floorIndex + 1, width: totalWidth, height: totalHeight };
    }).filter((f): f is NonNullable<typeof f> => f !== null);

    if (processedFloors.length === 0) return { fits: true };

    const numFloors = processedFloors.length;
    const totalContentWidth = processedFloors.reduce((sum, f) => sum + f.width, 0);
    const totalContentHeight = processedFloors.reduce((sum, f) => sum + f.height, 0);
    const minGap = 8 * NOMINAL_DOT_SPACING;

    if (isLandscape) {
        const overallHeight = Math.max(...processedFloors.map(f => f.height));
        const idealGap = (availableWidth - totalContentWidth) / (numFloors + 1);
        const gridAlignedGap = Math.max(minGap, Math.floor(idealGap / NOMINAL_DOT_SPACING) * NOMINAL_DOT_SPACING);
        const overallWidth = totalContentWidth + (numFloors > 1 ? (numFloors - 1) * gridAlignedGap : 0);
        return { fits: overallWidth <= availableWidth && overallHeight <= availableHeight };
    } else { // Portrait
        const overallWidth = Math.max(...processedFloors.map(f => f.width));
        const idealGap = (availableHeight - totalContentHeight) / (numFloors + 1);
        const gridAlignedGap = Math.max(minGap, Math.floor(idealGap / NOMINAL_DOT_SPACING) * NOMINAL_DOT_SPACING);
        const overallHeight = totalContentHeight + (numFloors > 1 ? (numFloors - 1) * gridAlignedGap : 0);
        return { fits: overallWidth <= availableWidth && overallHeight <= availableHeight };
    }
};
// --- END: Refactored function ---


export const calculatePdfLayoutData = (
  present: AppState['present'],
  drawingLayers: AppState['drawingLayers'],
  firstFloorDeduction: AppState['firstFloorDeduction'],
  stairDeductions: AppState['stairDeductions'],
  pageWidth: number,
  pageHeight: number
) => {
    const BORDER_MARGIN = 10;
    const availableWidth = pageWidth - BORDER_MARGIN * 2;
    const availableHeight = pageHeight - BORDER_MARGIN * 2;
    const areaResult = calculateArea(present, firstFloorDeduction, stairDeductions);

    const allUnitPositions: { unit: PlacedUnit; r: number; c: number; floor: number }[] = [];
    present.forEach((floorGrid, floor) => {
        floorGrid.forEach((row, r) => {
            row.forEach((unit, c) => {
                if (unit) allUnitPositions.push({ unit, r, c, floor });
            });
        });
    });

    if (allUnitPositions.length === 0) {
        const drawingTopLeft = { x: BORDER_MARGIN, y: BORDER_MARGIN };
        const gridDotOrigin = {
            x: ((drawingTopLeft.x % NOMINAL_DOT_SPACING) + NOMINAL_DOT_SPACING) % NOMINAL_DOT_SPACING,
            y: ((drawingTopLeft.y % NOMINAL_DOT_SPACING) + NOMINAL_DOT_SPACING) % NOMINAL_DOT_SPACING,
        };
        return { 
            BORDER_MARGIN, 
            positionedFloors: [], 
            areaResult, 
            gridDotOrigin, 
            drawingTopLeft, 
            NOMINAL_DOT_SPACING 
        };
    }

    const uniqueRows = [...new Set(allUnitPositions.map(u => u.r))].sort((a, b) => a - b);
    const uniqueCols = [...new Set(allUnitPositions.map(u => u.c))].sort((a, b) => a - b);

    const rowHeights = Object.fromEntries(uniqueRows.map(r => 
        [r, Math.max(0, ...allUnitPositions.filter(u => u.r === r).map(u => u.unit.dimensions.tsuma))]
    ));
    const colWidths = Object.fromEntries(uniqueCols.map(c => 
        [c, Math.max(0, ...allUnitPositions.filter(u => u.c === c).map(u => u.unit.dimensions.keta))]
    ));

    const rowOffsets: { [key: number]: number } = {};
    if (uniqueRows.length > 0) {
        rowOffsets[uniqueRows[0]] = 0;
        let currentY = 0;
        for (let i = 0; i < uniqueRows.length - 1; i++) {
            const r1 = uniqueRows[i], r2 = uniqueRows[i+1];
            currentY += (rowHeights[r1] || 0) + (r2 - r1) * GAP_SIZE;
            rowOffsets[r2] = currentY;
        }
    }

    const colOffsets: { [key: number]: number } = {};
    if (uniqueCols.length > 0) {
        colOffsets[uniqueCols[0]] = 0;
        let currentX = 0;
        for (let i = 0; i < uniqueCols.length - 1; i++) {
            const c1 = uniqueCols[i], c2 = uniqueCols[i+1];
            currentX += (colWidths[c1] || 0) + (c2 - c1) * GAP_SIZE;
            colOffsets[c2] = currentX;
        }
    }

    let refFloorNumber = 0;
    let refUnitPositions = allUnitPositions.filter(p => p.floor === 0);
    if (refUnitPositions.length === 0) {
        refFloorNumber = Math.min(...allUnitPositions.map(p => p.floor));
        refUnitPositions = allUnitPositions.filter(p => p.floor === refFloorNumber);
    }

    const refRects = refUnitPositions.map(fu => {
        const { unit, r, c } = fu;
        const width = unit.dimensions.keta;
        const height = unit.dimensions.tsuma;
        let x = colOffsets[c] ?? 0;
        let y = rowOffsets[r] ?? 0;
        if (unit.hAlign === 'right') x += (colWidths[c] ?? 0) - width;
        if (unit.vAlign === 'bottom') y += (rowHeights[r] ?? 0) - height;
        return { x, y, width, height };
    });
    const minX_ref = refRects.length > 0 ? Math.min(...refRects.map(r => r.x)) : 0;
    const minY_ref = refRects.length > 0 ? Math.min(...refRects.map(r => r.y)) : 0;

    const floors = present.map((floorGrid, index) => {
        const units: { unit: PlacedUnit; r: number; c: number }[] = [];
        floorGrid.forEach((row, r) => {
            row.forEach((unit, c) => {
                if(unit) units.push({ unit, r, c });
            });
        });
        return { floorIndex: index, units };
    }).filter(f => f.units.length > 0);

    let processedFloors = floors.map(({ floorIndex, units: floorUnits }) => {
        const unitRectsWithUnits = floorUnits.map(fu => {
            const { unit, r, c } = fu;
            const width = unit.dimensions.keta, height = unit.dimensions.tsuma;
            let x = colOffsets[c] ?? 0, y = rowOffsets[r] ?? 0;
            if (unit.hAlign === 'right') x += (colWidths[c] ?? 0) - width;
            if (unit.vAlign === 'bottom') y += (rowHeights[r] ?? 0) - height;
            return { x, y, width, height, r, c, unit };
        });

        if (unitRectsWithUnits.length === 0) return null;

        const rectsForWallCalc: UnitRect[] = unitRectsWithUnits.map(({unit, ...rest}) => rest);
        const rectMap = new Map<string, typeof unitRectsWithUnits[0]>();
        unitRectsWithUnits.forEach(rect => rectMap.set(`${rect.r},${rect.c}`, rect));

        unitRectsWithUnits.forEach(rectA => {
            const { r, c } = rectA;

            const rectB_right = rectMap.get(`${r},${c + 1}`);
            if (rectB_right) {
                const y_overlap_start = Math.max(rectA.y, rectB_right.y);
                const y_overlap_end = Math.min(rectA.y + rectA.height, rectB_right.y + rectB_right.height);
                const overlap_height = y_overlap_end - y_overlap_start;

                if (overlap_height > 0.01) {
                    rectsForWallCalc.push({ x: rectA.x + rectA.width, y: y_overlap_start, width: GAP_SIZE, height: overlap_height, r: -1, c: -1 });
                }
            }

            const rectB_bottom = rectMap.get(`${r + 1},${c}`);
            if (rectB_bottom) {
                const x_overlap_start = Math.max(rectA.x, rectB_bottom.x);
                const x_overlap_end = Math.min(rectA.x + rectA.width, rectB_bottom.x + rectB_bottom.width);
                const overlap_width = x_overlap_end - x_overlap_start;

                if (overlap_width > 0.01) {
                    rectsForWallCalc.push({ x: x_overlap_start, y: rectA.y + rectA.height, width: overlap_width, height: GAP_SIZE, r: -1, c: -1 });
                }
            }

            // --- Tanoji (2x2) intersection fill ---
            const rect_TR = rectB_right; // From above
            const rect_BL = rectB_bottom; // From above
            const rect_BR = rectMap.get(`${r + 1},${c + 1}`);

            if (rect_TR && rect_BL && rect_BR) {
                const unitA = rectA.unit;
                const unitTR = rect_TR.unit;
                const unitBL = rect_BL.unit;
                const unitBR = rect_BR.unit;

                const touchesBottomA = unitA.vAlign === 'bottom' || unitA.dimensions.tsuma === rowHeights[r];
                const touchesRightA = unitA.hAlign === 'right' || unitA.dimensions.keta === colWidths[c];

                const touchesBottomTR = unitTR.vAlign === 'bottom' || unitTR.dimensions.tsuma === rowHeights[r];
                const touchesLeftTR = unitTR.hAlign === 'left' || unitTR.dimensions.keta === (colWidths[c + 1] ?? 0);

                const touchesTopBL = unitBL.vAlign === 'top' || unitBL.dimensions.tsuma === (rowHeights[r + 1] ?? 0);
                const touchesRightBL = unitBL.hAlign === 'right' || unitBL.dimensions.keta === colWidths[c];

                const touchesTopBR = unitBR.vAlign === 'top' || unitBR.dimensions.tsuma === (rowHeights[r + 1] ?? 0);
                const touchesLeftBR = unitBR.hAlign === 'left' || unitBR.dimensions.keta === (colWidths[c + 1] ?? 0);

                if (touchesBottomA && touchesRightA && touchesBottomTR && touchesLeftTR &&
                    touchesTopBL && touchesRightBL && touchesTopBR && touchesLeftBR) {

                    const gapX = colOffsets[c] + colWidths[c];
                    const gapY = rowOffsets[r] + rowHeights[r];
                    rectsForWallCalc.push({ x: gapX, y: gapY, width: GAP_SIZE, height: GAP_SIZE, r: -1, c: -1 });
                }
            }
        });

        const innerWallPaths = _calculatePerimeterPaths(rectsForWallCalc);

        const expandedRects = rectsForWallCalc.map(rect => ({
          ...rect, x: rect.x - WALL_THICKNESS, y: rect.y - WALL_THICKNESS,
          width: rect.width + (WALL_THICKNESS * 2), height: rect.height + (WALL_THICKNESS * 2)
        }));
        const outerWallPaths = _calculatePerimeterPaths(expandedRects);

        const pillarCoords = generatePillarCoords(floorUnits, colOffsets, rowOffsets, colWidths, rowHeights);

        const minX = Math.min(...unitRectsWithUnits.map(r => r.x));
        const minY = Math.min(...unitRectsWithUnits.map(r => r.y));
        const maxX = Math.max(...unitRectsWithUnits.map(r => r.x + r.width));
        const maxY = Math.max(...unitRectsWithUnits.map(r => r.y + r.height));

        return { floorNumber: floorIndex + 1, minX, minY, maxX, maxY, width: maxX - minX, height: maxY - minY, units: floorUnits, unitRects: unitRectsWithUnits, innerWallPaths, outerWallPaths, pillarCoords, PILLAR_SIZE };
    }).filter((f): f is NonNullable<typeof f> => f !== null);

    processedFloors.sort((a, b) => a.floorNumber - b.floorNumber);

    const overallMinX = Math.min(...processedFloors.map(f => f.minX));
    const overallMinY = Math.min(...processedFloors.map(f => f.minY));
    const overallBuildingWidth = Math.max(...processedFloors.map(f => f.maxX)) - overallMinX;
    const overallBuildingHeight = Math.max(...processedFloors.map(f => f.maxY)) - overallMinY;

    const isLandscape = pageWidth > pageHeight;
    const numFloors = processedFloors.length;

    const totalContentWidth = processedFloors.reduce((sum, f) => sum + f.width, 0);
    const totalContentHeight = processedFloors.reduce((sum, f) => sum + f.height, 0);

    let drawingAreaX, drawingAreaY, gap;

    if (isLandscape) {
        const idealGap = (availableWidth - totalContentWidth) / (numFloors + 1);
        gap = Math.max(8 * NOMINAL_DOT_SPACING, Math.floor(idealGap / NOMINAL_DOT_SPACING) * NOMINAL_DOT_SPACING);
        const finalOverallWidth = totalContentWidth + (numFloors > 1 ? (numFloors - 1) * gap : 0);
        drawingAreaX = (availableWidth - finalOverallWidth) / 2;
        drawingAreaY = (availableHeight - overallBuildingHeight) / 2;
    } else {
        const idealGap = (availableHeight - totalContentHeight) / (numFloors + 1);
        gap = Math.max(8 * NOMINAL_DOT_SPACING, Math.floor(idealGap / NOMINAL_DOT_SPACING) * NOMINAL_DOT_SPACING);
        const finalOverallHeight = totalContentHeight + (numFloors > 1 ? (numFloors - 1) * gap : 0);
        drawingAreaY = (availableHeight - finalOverallHeight) / 2;
        drawingAreaX = (availableWidth - overallBuildingWidth) / 2;
    }

    let currentOffset = isLandscape ? drawingAreaX : drawingAreaY;
    const positionedFloors = processedFloors.map(floor => {
        const tx = isLandscape ? currentOffset - floor.minX : drawingAreaX - overallMinX;
        const ty = isLandscape ? drawingAreaY - overallMinY : currentOffset - floor.minY;

        if (isLandscape) {
            currentOffset += floor.width + gap;
        } else {
            currentOffset += floor.height + gap;
        }
        return { ...floor, tx, ty };
    });

    const refPositionedFloor = positionedFloors.find(f => f.floorNumber === refFloorNumber + 1);
    let gridDotOrigin;
    let drawingTopLeft = { x: BORDER_MARGIN, y: BORDER_MARGIN };

    if (refPositionedFloor) {
        const drawingTopLeftX = BORDER_MARGIN + refPositionedFloor.tx + minX_ref;
        const drawingTopLeftY = BORDER_MARGIN + refPositionedFloor.ty + minY_ref;
        drawingTopLeft = { x: drawingTopLeftX, y: drawingTopLeftY };

        gridDotOrigin = {
          x: ((drawingTopLeftX % NOMINAL_DOT_SPACING) + NOMINAL_DOT_SPACING) % NOMINAL_DOT_SPACING,
          y: ((drawingTopLeftY % NOMINAL_DOT_SPACING) + NOMINAL_DOT_SPACING) % NOMINAL_DOT_SPACING,
        };
    } else {
        gridDotOrigin = { x: BORDER_MARGIN, y: BORDER_MARGIN };
    }

    return { BORDER_MARGIN, positionedFloors, areaResult, gridDotOrigin, drawingTopLeft, NOMINAL_DOT_SPACING };
}

export const calculateViewBoundingBox = (
    { present, drawingLayers, firstFloorDeduction, stairDeductions }: Pick<AppState, 'present' | 'drawingLayers' | 'firstFloorDeduction' | 'stairDeductions'>,
    view: 'all' | 1 | 2 | 3,
    pageWidth: number,
    pageHeight: number
): { x: number; y: number; width: number; height: number } | null => {
    // If the view is 'all', the bounding box is the entire page.
    if (view === 'all') {
        return {
            x: 0,
            y: 0,
            width: pageWidth,
            height: pageHeight,
        };
    }

    // For a specific floor, first calculate the full layout for ALL floors.
    // This gives us the correct position of the target floor within the overall drawing.
    const layoutData = calculatePdfLayoutData(present, drawingLayers, firstFloorDeduction, stairDeductions, pageWidth, pageHeight);

    // If there's no layout data (e.g., no units placed at all), fall back to the whole page.
    if (layoutData.positionedFloors.length === 0) {
        return { x: 0, y: 0, width: pageWidth, height: pageHeight };
    }

    const { positionedFloors, BORDER_MARGIN } = layoutData;
    const targetFloor = positionedFloors.find(f => f.floorNumber === view);

    // If the target floor doesn't exist in the layout (e.g., has no units), fall back to the whole page.
    if (!targetFloor) {
        return { x: 0, y: 0, width: pageWidth, height: pageHeight };
    }

    // The floor exists, so calculate its bounding box on the page.
    const padding = WALL_THICKNESS + 5; // Add some margin around the floor plan.

    const minX = BORDER_MARGIN + targetFloor.tx + targetFloor.minX - padding;
    const minY = BORDER_MARGIN + targetFloor.ty + targetFloor.minY - padding;
    const maxX = BORDER_MARGIN + targetFloor.tx + targetFloor.maxX + padding;
    const maxY = BORDER_MARGIN + targetFloor.ty + targetFloor.maxY + padding;

    return {
        x: minX,
        y: minY,
        width: maxX - minX,
        height: maxY - minY,
    };
};

