export function getPathAsPoints(path: DrawingPath, isHandwritingMode: boolean, applyVisualEffects: boolean = true): DrawingPoint[][] {
    // Use path-specific setting if available, otherwise fallback to global
    const effectiveHandwriting = path.isHandwriting !== undefined ? path.isHandwriting : isHandwritingMode;

    // For geometric calculations (like snapping), we never want the handwriting effect,
    // regardless of the global setting.
    const useHandwriting = applyVisualEffects && effectiveHandwriting && path.tool !== 'marker' && path.tool !== 'pencil';
    const interpolatedPoints = getInterpolatedPoints(path, useHandwriting);

    // If we don't need to apply visual effects, return the pure geometric path.
    if (!applyVisualEffects) {
        return [interpolatedPoints];
    }

    // For freehand tools, we ignore lineType and just return the interpolated points.
    if (path.tool === 'pencil' || path.tool === 'marker') {
        const useFreehandStyle = applyVisualEffects && effectiveHandwriting;
        return [useFreehandStyle ? generateHandwritingPath(path.points) : path.points];
    }

    switch (path.lineType) {
        case 'wavy':
            return [generateWavyPath(interpolatedPoints, path.strokeWidth)];
        case 'double': {
            const offset = path.strokeWidth / 2 + 0.1;
            const p1 = calculateOffsetPath(interpolatedPoints, -offset);
            const p2 = calculateOffsetPath(interpolatedPoints, offset);
            return [p1, p2];
        }
        case 'child-bearing': {
            const offset = path.strokeWidth * 0.4;
            const p1 = calculateOffsetPath(interpolatedPoints, -offset);
            const p2 = calculateOffsetPath(interpolatedPoints, offset);
            return [p1, p2];
        }
        default:
            return [interpolatedPoints];
    }
}


/**
 * Decomposes a set of potentially overlapping rectangles into a set of smaller,
 * non-overlapping rectangles that perfectly tile the original area.
 * This is a preprocessing step for finding the perimeter of a complex shape
 * made of multiple rectangles.
 * @param rects An array of UnitRect objects.
 * @returns An array of new, non-overlapping UnitRect objects.
 */
const decomposeRects = (rects: UnitRect[]): UnitRect[] => {
    if (rects.length === 0) return [];

    const xCoords = new Set<number>();
    const yCoords = new Set<number>();
    rects.forEach(rect => {
        xCoords.add(rect.x);
        xCoords.add(rect.x + rect.width);
        yCoords.add(rect.y);
        yCoords.add(rect.y + rect.height);
    });
    const sortedX = [...xCoords].sort((a,b)=>a-b);
    const sortedY = [...yCoords].sort((a,b)=>a-b);

    const newRects: UnitRect[] = [];
    const tolerance = 0.001;

    for (let i = 0; i < sortedX.length - 1; i++) {
        for (let j = 0; j < sortedY.length - 1; j++) {
            const x = sortedX[i];
            const y = sortedY[j];
            const w = sortedX[i+1] - x;
            const h = sortedY[j+1] - y;

            if (w < tolerance || h < tolerance) continue;

            const midX = x + w / 2;
            const midY = y + h / 2;

            for (const rect of rects) {
                if (midX > rect.x - tolerance && midX < rect.x + rect.width + tolerance &&
                    midY > rect.y - tolerance && midY < rect.y + rect.height + tolerance) {
                    newRects.push({x, y, width: w, height: h, r: -1, c: -1});
                    break;
                }
            }
        }
    }
    return newRects;
}

/**
 * Calculates the perimeter paths of a shape defined by a collection of rectangles.
 * It works by decomposing the rectangles, counting shared edges, and then tracing
 * the edges that are only used once (i.e., the exterior boundary).
 * @param rects An array of UnitRect objects representing the shape.
 * @returns An array of SVG path data strings (`d` attribute).
 */
const _calculatePerimeterPaths = (rects: UnitRect[]): string[] => {
    const tolerance = 0.01;
    const round = (n: number) => parseFloat(n.toFixed(4));

    const decomposedRects = decomposeRects(rects);
    if (decomposedRects.length === 0) return [];

    const xCoords = new Set<number>();
    const yCoords = new Set<number>();
    decomposedRects.forEach(rect => {
        const { x, y, width, height } = rect;
        xCoords.add(round(x));
        xCoords.add(round(x + width));
        yCoords.add(round(y));
        yCoords.add(round(y + height));
    });

    const sortedX = Array.from(xCoords).sort((a, b) => a - b);
    const sortedY = Array.from(yCoords).sort((a, b) => a - b);

    const allSegments: Edge[] = [];
    decomposedRects.forEach(rect => {
        const r_x1 = round(rect.x);
        const r_y1 = round(rect.y);
        const r_x2 = round(rect.x + rect.width);
        const r_y2 = round(rect.y + rect.height);

        [r_y1, r_y2].forEach(y => {
            const relevantX = sortedX.filter(x => x >= r_x1 - tolerance && x <= r_x2 + tolerance);
            for (let i = 0; i < relevantX.length - 1; i++) {
                allSegments.push({ x1: relevantX[i], y1: y, x2: relevantX[i+1], y2: y });
            }
        });

        [r_x1, r_x2].forEach(x => {
            const relevantY = sortedY.filter(y => y >= r_y1 - tolerance && y <= r_y2 + tolerance);
            for (let i = 0; i < relevantY.length - 1; i++) {
                allSegments.push({ x1: x, y1: relevantY[i], x2: x, y2: relevantY[i+1] });
            }
        });
    });

    const edgeCount = new Map<string, number>();
    const getEdgeKey = (x1: number, y1: number, x2: number, y2: number) => {
      const r = (n: number) => round(n);
      return r(x1) < r(x2) || (r(x1) === r(x2) && r(y1) < r(y2)) ? `${r(x1)},${r(y1)},${r(x2)},${r(y2)}` : `${r(x2)},${r(y2)},${r(x1)},${r(y1)}`;
    };

    allSegments.forEach(seg => {
      if (Math.abs(seg.x1 - seg.x2) < tolerance && Math.abs(seg.y1 - seg.y2) < tolerance) return;
      const key = getEdgeKey(seg.x1, seg.y1, seg.x2, seg.y2);
      edgeCount.set(key, (edgeCount.get(key) || 0) + 1);
    });

    const boundaryEdges: Edge[] = [];
    edgeCount.forEach((count, key) => {
      if (count % 2 !== 0) {
        const [x1, y1, x2, y2] = key.split(',').map(parseFloat);
        boundaryEdges.push({ x1, y1, x2, y2 });
      }
    });

    const paths = [];
    while(boundaryEdges.length > 0) {
      let edge = boundaryEdges.pop()!;
      let path = `M ${round(edge.x1)} ${round(edge.y1)} L ${round(edge.x2)} ${round(edge.y2)}`;
      let currentPoint = { x: edge.x2, y: edge.y2 };
      const startPoint = { x: edge.x1, y: edge.y1 };

      for (let i = 0; i < boundaryEdges.length * 2; i++) {
        let found = false;
        for (let j = boundaryEdges.length - 1; j >= 0; j--) {
          const next = boundaryEdges[j];
          const p1Match = Math.abs(next.x1 - currentPoint.x) < tolerance && Math.abs(next.y1 - currentPoint.y) < tolerance;
          const p2Match = Math.abs(next.x2 - currentPoint.x) < tolerance && Math.abs(next.y2 - currentPoint.y) < tolerance;

          if (p1Match || p2Match) {
            const nextPoint = p1Match ? { x: next.x2, y: next.y2 } : { x: next.x1, y: next.y1 };
            path += ` L ${round(nextPoint.x)} ${round(nextPoint.y)}`;
            currentPoint = nextPoint;
            boundaryEdges.splice(j, 1);
            found = true;
            break;
          }
        }
        if (Math.abs(currentPoint.x - startPoint.x) < tolerance && Math.abs(currentPoint.y - startPoint.y) < tolerance) {
          path += ' Z';
          break;
        }
        if (!found) break;
      }
      paths.push(path);
    }
    return paths;
};

const generatePillarCoords = (
  floorUnits: { unit: PlacedUnit; r: number; c: number }[],
  colOffsets: { [key: number]: number },
  rowOffsets: { [key: number]: number },
  colWidths: { [key: number]: number },
  rowHeights: { [key: number]: number }
): Set<string> => {
    const pillarCoords = new Set<string>();

    floorUnits.forEach(({ unit, r, c }) => {
      if (unit.type !== 'main') return;

      const w = unit.dimensions.keta;
      const h = unit.dimensions.tsuma;
      let ux = colOffsets[c] ?? 0;
      let uy = rowOffsets[r] ?? 0;

      if (unit.hAlign === 'right') ux += (colWidths[c] ?? 0) - w;
      if (unit.vAlign === 'bottom') uy += (rowHeights[r] ?? 0) - h;

      const pillarPositions = [
        { x: ux - PILLAR_SIZE, y: uy - PILLAR_SIZE },
        { x: ux + w, y: uy - PILLAR_SIZE },
        { x: ux - PILLAR_SIZE, y: uy + h },
        { x: ux + w, y: uy + h },
      ];

      pillarPositions.forEach(pos => {
        pillarCoords.add(`${pos.x.toFixed(4)},${pos.y.toFixed(4)}`);
      });
    });

    return pillarCoords;
};

